steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      teams(name: \"Mobile\") {
        nodes {
          id
          name
        }
      }
      users(includeDisabled: true) {
        nodes {
          id
          name
          displayName
        }
      }
      workflowStates {
        nodes {
          id
          name
          type
          team {
            id
            name
          }
        }
      }
    }
  }'
